# Since the problem involves Stable Roommates Problem, which is known to:
# 1. Sometimes have no stable solution
# 2. Require complex algorithms like Irving's algorithm
# 
# We'll implement a proper solution that checks for stable matchings.

class Solution:
    def __init__(self):
        pass

    def parse_input(self, input_string: str) -> Tuple[int, List[List[int]]]:
        lines = input_string.strip().split('\n')
        n = int(lines[0])
        costs = []
        for i in range(n):
            row = list(map(int, lines[1 + i].split()))
            costs.append(row)
        return n, costs

    def build_prefs(self, n: int, costs: List[List[int]]) -> List[List[int]]:
        # Build preference lists for each city (lower cost = higher preference)
        prefs = []
        for i in range(n):
            # Input format: skip A_{i,i}, so we need to map indices correctly
            preference_list = []
            idx = 0
            for j in range(n):
                if j == i:
                    continue
                # A[j] in the input corresponds to cost between i and some j
                # where j < i is at original position j, and j > i is at position j-1
                val = costs[i][idx]
                preference_list.append((j, val))
                idx += 1
            preference_list.sort(key=lambda x: x[1])  # Lower cost = higher preference
            prefs.append([item[0] for item in preference_list])
        return prefs

    def preference_rank(self, prefs: List[List[int]], i: int, j: int) -> int:
        """Return rank of city j in city i's preference list (lower = better)"""
        return prefs[i].index(j)

