def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        clauses.append(parts[1:])

    if n == 0:
        return "YES\n" + ''.join(['0'] * m)

    # Literal to node mapping
    # Node i: literal xi (positive form)
    # Node i+m: literal -xi (negative form)
    def literal_to_node(x):
        x_abs = abs(x)
        x_idx = x_abs - 1
        if x > 0:
            return x_idx
        else:
            return x_idx + m

    # Complement node
    def neg(u):
        return u ^ m

    # Build implication graph
    # For clause (l1 | l2 | ... | lk), implications: ~li => lj for all i != j
    adj = [[] for _ in range(2 * m)]

    for clause in clauses:
        literals = [literal_to_node(x) for x in clause]
        # Create implications between all distinct pairs
        for i in range(len(literals)):
            for j in range(i + 1, len(literals)):
                # ~l_i => l_j and ~l_j => l_i
                adj[neg(literals[i])].append(literals[j])
                adj[neg(literals[j])].append(literals[i])

    # Tarjan's algorithm for SCC
    ids = [None] * (2 * m)
    low = [None] * (2 * m)
    scc = [None] * (2 * m)
    on_stack = [False] * (2 * m)
    stack = []
    id_counter = 0
    scc_id = 0

    def dfs(u):
        nonlocal id_counter, scc_id
        ids[u] = low[u] = id_counter
        id_counter += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if ids[v] is None:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            while stack:
                w = stack.pop()
                on_stack[w] = False
                scc[w] = scc_id
                if w == u:
                    break
            scc_id += 1

    for i in range(2 * m):
        if ids[i] is None:
            dfs(i)

    # Check satisfiability
    for i in range(1, m + 1):
        u1 = literal_to_node(i)
        u2 = literal_to_node(-i)
        if scc[u1] == scc[u2]:
            return "NO"

    # Construct assignment
    assignment = [0] * m
    for i in range(1, m + 1):
        u1 = literal_to_node(i)
        u2 = literal_to_node(-i)
        # If positive literal is in higher SCC, set variable to 1
        if scc[u1] > scc[u2]:
            assignment[i-1] = 1

    return "YES\n" + ''.join(map(str, assignment))

