    """For a given prime g, compute minimum cost to make all elements divisible by g"""
    INF = float('inf')

    # Calculate cost for each element (0 if divisible, b if can be changed by ±1, a if must remove)
    costs = []
    for x in arr:
        r = x % g
        if r == 0:
            costs.append(0)
        elif r == 1 or r == g - 1:
            costs.append(b)
        else:
            costs.append(a)  # Must remove this element

    # Sliding window DP to find max savings from removal
    # We save cost[i] but pay 'a' for removal; net change is cost[i] - a
    dp = 0
    best = 0

    for x in costs:
        # max(0, keep previous, start new at current)
        if dp + x - a > x - a:
            dp = dp + x - a
        else:
            dp = x - a
        best = max(best, dp)

    return (sum(costs) - best)


