from collections import deque

def solution(n_str):
    """
    Find minimum operations to reduce n to 0 by repeatedly subtracting
    a digit that appears in the current number.
    """
    n = int(n_str)

    if n == 0:
        return '0\n'

    # BFS from n down to 0, memoizing visited states
    memo = {n: 0}
    queue = deque([n])

    while queue:
        current = queue.popleft()
        current_ops = memo[current]

        if current == 0:
            return str(current_ops) + '\n'

        # Get all unique digits in current number
        digits = set(str(current))

        for d in digits:
            if d != '0':  # Don't subtract 0 (no progress)
                next_val = current - int(d)
                if next_val not in memo:
                    memo[next_val] = current_ops + 1
                    queue.append(next_val)

    return '0\n'

